import heapq

def solve(dependencies):
    # Collect all nodes (keys + any node appearing as a prerequisite)
    all_nodes = set(dependencies.keys())
    for node, deps in dependencies.items():
        for dep in deps:
            all_nodes.add(dep)

    # Build adjacency list and in-degree counts, ignoring duplicate edges
    adj = {node: set() for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for node, deps in dependencies.items():
        for dep in set(deps):
            adj[dep].add(node)
            in_degree[node] += 1

    # Kahn's algorithm with a min-heap for lexicographically smallest choice
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(all_nodes):
        return None
    return result
