def solve(base, maximum, attempts):
    if base == 0 or maximum == 0:
        return [0] * len(attempts)

    # threshold is the smallest integer t such that base * t >= maximum
    threshold = (maximum + base - 1) // base

    # For attempt a, base * 2**a >= maximum iff 2**a >= threshold.
    # If a >= threshold.bit_length(), then 2**a > threshold, so result is maximum.
    # Otherwise a is small enough that base * (1 << a) is bounded by ~2*maximum.
    cutoff = threshold.bit_length()

    result = []
    for a in attempts:
        if a >= cutoff:
            result.append(maximum)
        else:
            val = base * (1 << a)
            if val > maximum:
                result.append(maximum)
            else:
                result.append(val)
    return result
